// Generate an input buffer that is readable for at least source_size bytes
// FUZZ_PARAM_STR returns 1..4096 bytes. We cap to <= 2048 for performance.
std::string buf = FUZZ_PARAM_STR();
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 2048) + 1; // 1..2048
if (buf.size() > cap) { buf.resize(cap); }

// cbor_data is an alias for const unsigned char*
