// Enforce: item must be a CBOR array constructed by our constructors
int is_array = !strcmp(FUZZ_GET_ATTR_STR(item, "kind"), "array");
if (!is_array) { FUZZ_BAIL(); }

// Call target function
size_t sz = cbor_array_size(item);

// Basic property: for arrays, size should be >= 0 (always true for size_t)
// We also opportunistically read attributes if present, but do not assume consistency
(void)sz;

// Validation: Input item is returned to the pool; no side-effects expected
