// Randomly enable some callbacks; others remain NULL (ignored by decoder).
if (rnd & 1u)   cbs.uint8 = cb_uint8;            if (rnd & 2u)   cbs.uint16 = cb_uint16;
if (rnd & 4u)   cbs.uint32 = cb_uint32;          if (rnd & 8u)   cbs.uint64 = cb_uint64;
if (rnd & 16u)  cbs.negint64 = cb_uint64;        if (rnd & 32u)  cbs.negint32 = cb_uint32;
if (rnd & 64u)  cbs.negint16 = cb_uint16;        if (rnd & 128u) cbs.negint8 = cb_uint8;
if (rnd & 256u) cbs.byte_string_start = cb_simple;
if (rnd & 512u) cbs.byte_string = cb_string;     if (rnd & 1024u) cbs.string = cb_string;
if (rnd & 2048u) cbs.string_start = cb_simple;   if (rnd & 4096u) cbs.indef_array_start = cb_simple;
if (rnd & 8192u) cbs.array_start = cb_coll;      if (rnd & 16384u) cbs.indef_map_start = cb_simple;
