// Adjust our hint counter; do not access item afterwards to avoid UAF if freed.
int hinted = FUZZ_GET_ATTR_INT(item, "hint_refcount");
if (hinted > 0) { FUZZ_SET_ATTR_INT(item, "hint_refcount", hinted - 1); }
