import random
import struct
import math

# CBOR major types and helpers per RFC 8949
_MT_UINT = 0x00
_MT_NEGINT = 0x20
_MT_BYTES = 0x40
_MT_TEXT = 0x60
_MT_ARRAY = 0x80
_MT_MAP = 0xA0
_MT_TAG = 0xC0
_MT_SIMPLE = 0xE0
_BRK = 0xFF

# Encode the additional information for length/value

def _enc_ai(mt: int, n: int) -> bytes:
    if n < 24:
        return bytes([mt | n])
    elif n <= 0xFF:
        return bytes([mt | 24, n & 0xFF])
    elif n <= 0xFFFF:
        return bytes([mt | 25]) + struct.pack('>H', n)
    elif n <= 0xFFFFFFFF:
        return bytes([mt | 26]) + struct.pack('>I', n)
    else:
        return bytes([mt | 27]) + struct.pack('>Q', n)


def enc_uint(n: int) -> bytes:
    if n < 0:
        n = 0
    return _enc_ai(_MT_UINT, n)


def enc_negint(n: int) -> bytes:
    # For logical negative x, CBOR stores -(x+1) as unsigned magnitude
    if n >= 0:
        n = 0
    mag = (-n) - 1
    if mag < 0:
        mag = 0
    return _enc_ai(_MT_NEGINT, mag)


def enc_bytes(b: bytes) -> bytes:
    return _enc_ai(_MT_BYTES, len(b)) + b


def enc_text(s: str) -> bytes:
    b = s.encode('utf-8', errors='strict')
    return _enc_ai(_MT_TEXT, len(b)) + b


def enc_array(items: list[bytes]) -> bytes:
    return _enc_ai(_MT_ARRAY, len(items)) + b''.join(items)


def enc_indef_array(chunks: list[bytes]) -> bytes:
    return bytes([_MT_ARRAY | 31]) + b''.join(chunks) + bytes([_BRK])


def enc_map(pairs: list[tuple[bytes, bytes]]) -> bytes:
    return _enc_ai(_MT_MAP, len(pairs)) + b''.join(k + v for k, v in pairs)


def enc_indef_map(pairs: list[tuple[bytes, bytes]]) -> bytes:
    body = b''.join(k + v for k, v in pairs)
    return bytes([_MT_MAP | 31]) + body + bytes([_BRK])


def enc_tag(tag: int, item: bytes) -> bytes:
    return _enc_ai(_MT_TAG, tag) + item


def enc_bool(v: bool) -> bytes:
    return bytes([_MT_SIMPLE | (21 if v else 20)])


def enc_null() -> bytes:
    return bytes([_MT_SIMPLE | 22])


def enc_undef() -> bytes:
    return bytes([_MT_SIMPLE | 23])


def enc_half(f: float) -> bytes:
    # Encode half-precision float: major type 7, ai=25, 2 bytes payload
    # Convert Python float to IEEE-754 binary16
    f32 = float(f)
    # Handle special cases
    if math.isnan(f32):
        bits = 0x7E00  # qNaN
    elif math.isinf(f32):
        bits = 0x7C00 if f32 > 0 else 0xFC00
    else:
        sign = 0
        if math.copysign(1.0, f32) < 0:
            sign = 1
            f32 = -f32
        m, e = math.frexp(f32)  # f = m * 2^(e), 0.5 <= m < 1.0
        # Translate to half-precision exponent/significand
        e = e - 1  # adjust because frexp gives m in [0.5,1)
        e_half = e + 15
        if e_half <= 0:
            # subnormal or zero
            frac = int(round(m * (2 ** (e + 10)))) if e + 10 >= 0 else 0
            if frac == 0:
                bits = sign << 15
            else:
                bits = (sign << 15) | frac
        elif e_half >= 31:
            # overflow to inf
            bits = (sign << 15) | 0x7C00
        else:
            frac = int(round((m * 2 - 1.0) * (1 << 10)))
            if frac == (1 << 10):
                # rounding caused carry
                e_half += 1
                frac = 0
                if e_half >= 31:
                    bits = (sign << 15) | 0x7C00
                else:
                    bits = (sign << 15) | (e_half << 10) | frac
            else:
                bits = (sign << 15) | (e_half << 10) | frac
    return bytes([_MT_SIMPLE | 25]) + struct.pack('>H', bits)


def enc_float(f: float) -> bytes:
    return bytes([_MT_SIMPLE | 26]) + struct.pack('>f', float(f))


def enc_double(d: float) -> bytes:
    return bytes([_MT_SIMPLE | 27]) + struct.pack('>d', float(d))


def _rand_utf8(rng: random.Random, maxlen: int) -> str:
    # Mix of ASCII, BMP, and some emoji range
    n = rng.randint(0, maxlen)
    chars = []
    for _ in range(n):
        t = rng.random()
        if t < 0.7:
            chars.append(chr(rng.randint(0x20, 0x7E)))
        elif t < 0.95:
            chars.append(chr(rng.randint(0x00A0, 0x07FF)))
        else:
            chars.append(chr(rng.randint(0x1F300, 0x1F6FF)))
    return ''.join(chars)


def _rand_bytes(rng: random.Random, maxlen: int) -> bytes:
    n = rng.randint(0, maxlen)
    return bytes(rng.getrandbits(8) for _ in range(n))


def _rand_uint(rng: random.Random) -> int:
    # Bias toward boundary values
    choices = [0, 1, 23, 24, 255, 256, 65535, 65536, 2**32-1, 2**32, 2**64-1]
    if rng.random() < 0.6:
        return rng.choice(choices)
    # general random 64-bit
    hi = rng.getrandbits(64)
    return hi


def _gen_scalar(rng: random.Random) -> bytes:
    k = rng.randrange(0, 10)
    if k == 0:
        return enc_uint(_rand_uint(rng))
    if k == 1:
        # negative integer with interesting magnitudes
        mags = [0, 1, 23, 24, 255, 256, 65535, 65536, 2**32-1]
        mag = rng.choice(mags)
        return _enc_ai(_MT_NEGINT, mag)
    if k == 2:
        return enc_bytes(_rand_bytes(rng, 64))
    if k == 3:
        return enc_text(_rand_utf8(rng, 64))
    if k == 4:
        return enc_bool(rng.choice([True, False]))
    if k == 5:
        return enc_null()
    if k == 6:
        return enc_undef()
    if k == 7:
        return enc_half(rng.uniform(-1e5, 1e5))
    if k == 8:
        return enc_float(rng.uniform(-1e10, 1e10))
    # k == 9
    return enc_double(rng.uniform(-1e300, 1e300))


def _gen_item(rng: random.Random, depth: int) -> bytes:
    if depth <= 0:
        # force scalar at max depth
        return _gen_scalar(rng)
    kind = rng.randrange(0, 8)
    if kind == 0:
        return _gen_scalar(rng)
    if kind == 1:
        # definite array
        n = rng.randint(0, 6)
        els = [_gen_item(rng, depth - 1) for _ in range(n)]
        return enc_array(els)
    if kind == 2:
        # indefinite array with mixed chunk sizes
        n = rng.randint(0, 5)
        chunks = [_gen_item(rng, depth - 1) for _ in range(n)]
        return enc_indef_array(chunks)
    if kind == 3:
        # definite map with diverse keys/values; keep keys simple for determinism
        n = rng.randint(0, 4)
        pairs = []
        for _ in range(n):
            # keys as text or small ints
            if rng.random() < 0.5:
                k = enc_text(_rand_utf8(rng, 12))
            else:
                k = enc_uint(rng.randrange(0, 100))
            v = _gen_item(rng, depth - 1)
            pairs.append((k, v))
        return enc_map(pairs)
    if kind == 4:
        # indefinite map
        n = rng.randint(0, 3)
        pairs = []
        for _ in range(n):
            k = enc_text(_rand_utf8(rng, 10)) if rng.random() < 0.6 else enc_uint(rng.randrange(0, 50))
            v = _gen_item(rng, depth - 1)
            pairs.append((k, v))
        return enc_indef_map(pairs)
    if kind == 5:
        # bytes/text with interesting lengths
        if rng.random() < 0.5:
            # definite bytes
            size_choices = [0, 1, 23, 24, 255, 256, 1024]
            n = rng.choice(size_choices)
            b = _rand_bytes(rng, min(n, 256))
            # ensure declared length equals actual
            return enc_bytes(b)
        else:
            # definite text
            s = _rand_utf8(rng, 80)
            return enc_text(s)
    if kind == 6:
        # tag common values: 0(date/time), 1(epoch), 2,3 bignums, 24(encoded cbor)
        tag_no = rng.choice([0, 1, 2, 3, 24, 32, 35, _rand_uint(rng) & 0xFFFFFFFF])
        item = _gen_item(rng, depth - 1)
        return enc_tag(tag_no, item)
    # kind == 7: composite of composites to enrich structure
    arr = []
    # prefix with a map then an array inside
    m_pairs = []
    for key in ["a", "b", "c"][:rng.randint(0, 3)]:
        m_pairs.append((enc_text(key), _gen_scalar(rng)))
    if m_pairs:
        arr.append(enc_map(m_pairs))
    # add a nested array
    arr.append(enc_array([_gen_scalar(rng) for _ in range(rng.randint(0, 4))]))
    return enc_array(arr)


def _cap(buf: bytes) -> bytes:
    # Ensure <= 4096 bytes; if larger, prefer to trim by reducing depth rather than truncating
    if len(buf) <= 4096:
        return buf
    # As a fallback, wrap a shorter item in a tag 24 (embedded CBOR) to keep validity while varying size
    # Generate a smaller scalar deterministically
    rng = random.Random(0)
    small = _gen_scalar(rng)
    out = enc_tag(24, small)
    return out if len(out) <= 4096 else out[:4096]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose one of several top-level shapes to exercise different code paths
    choice = rng.randrange(0, 10)
    if choice == 0:
        buf = _gen_scalar(rng)
    elif choice == 1:
        # small definite array of scalars
        n = rng.randint(0, 8)
        buf = enc_array([_gen_scalar(rng) for _ in range(n)])
    elif choice == 2:
        # nested arrays/maps
        buf = _gen_item(rng, depth=3)
    elif choice == 3:
        # indefinite array of mixed items
        n = rng.randint(0, 6)
        buf = enc_indef_array([_gen_item(rng, 2) for _ in range(n)])
    elif choice == 4:
        # definite map with mixed keys/values
        n = rng.randint(0, 6)
        pairs = []
        for i in range(n):
            key = enc_text(f"k{i}") if rng.random() < 0.7 else enc_uint(i)
            val = _gen_item(rng, 2)
            pairs.append((key, val))
        buf = enc_map(pairs)
    elif choice == 5:
        # tagged value (embedded CBOR when tag=24) to exercise tag handling
        inner = _gen_item(rng, 2)
        tag_no = rng.choice([24, 0, 1, 32, 35])
        buf = enc_tag(tag_no, inner)
    elif choice == 6:
        # bytestring with interesting boundary length plus following item to test single-item decode behavior
        # We will still generate a single item; use large bytes
        data = _rand_bytes(rng, rng.choice([0, 1, 23, 24, 255, 512, 1024]))
        buf = enc_bytes(data)
    elif choice == 7:
        # text with multi-byte UTF-8
        s = _rand_utf8(rng, 300)
        buf = enc_text(s)
    elif choice == 8:
        # floating numbers, include NaN/inf
        v = rng.random()
        if v < 0.33:
            buf = enc_half(float('nan'))
        elif v < 0.66:
            buf = enc_float(float('inf') if rng.random() < 0.5 else float('-inf'))
        else:
            buf = enc_double(rng.uniform(-1e308, 1e308))
    else:
        # Indefinite map mixing a few entries
        m = []
        for _ in range(rng.randint(0, 4)):
            k = enc_text(_rand_utf8(rng, 16)) if rng.random() < 0.7 else enc_uint(rng.randint(0, 50))
            v = _gen_item(rng, 2)
            m.append((k, v))
        buf = enc_indef_map(m)
    return _cap(buf)
